use semio_framework_pack_json::{JsonNativeSource,JsonBorrowNoContext,JsonNativeBorrow,JsonBorrowedSinkCursor};
use semio_framework_value::{RetainedCloneGrant,RetirementDemand,NativeEncodeControl};
use semio_os_mcp_schema::schema::{ArtifactInferenceRequestV1,ArtifactInferenceResultV1};
#[global_allocator]static HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn write(value:&impl JsonNativeBorrow)->String{let context=JsonBorrowNoContext;let source=JsonNativeSource{root:value,context:&context};let mut cursor=JsonBorrowedSinkCursor::empty(64).unwrap();let mut observer=|_|true;let mut control=NativeEncodeControl::new(100000,&mut observer);let mut output=Vec::new();for _ in 0..100000{if cursor.is_complete(){break}let mut bytes=[0;7];let g=grant(cursor.next_demands(bytes.len(),4096).unwrap());let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.step(&source,&mut bytes,g,1,&mut control));let step=step.result.unwrap();assert!(step.progress.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress.retained_capacity_bytes,step.progress.released_bytes));output.extend_from_slice(&bytes[..step.written_bytes]);}assert!(cursor.is_complete());for _ in 0..100000{if cursor.terminal_is_empty(){break}let g=grant(cursor.close_demands(4096).unwrap());let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close_step(g));let p=step.result.unwrap().progress();assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}assert!(cursor.terminal_is_empty());String::from_utf8(output).unwrap()}
#[test]fn inference_native_fields_match_the_shared_wire_and_serde_with_exact_sink_heap_receipts(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let expected=row["expected"].as_str().unwrap();let text=serde_json::to_string(&row["input"]).unwrap();match row["kind"].as_str().unwrap(){"request"=>{let value:ArtifactInferenceRequestV1=serde_json::from_str(&text).unwrap();assert_eq!(serde_json::to_string(&value).unwrap(),expected);assert_eq!(write(&value),expected)},"result"=>{let value:ArtifactInferenceResultV1=serde_json::from_str(&text).unwrap();assert_eq!(serde_json::to_string(&value).unwrap(),expected);assert_eq!(write(&value),expected)},_=>panic!("unknown inference fixture")}}}
